arguments.new_str:
namespace Payments;

public interface IPaymentProvider
{
    Task<ChargeResult> ProcessChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default);
    Task<RefundResult> ProcessRefundAsync(string chargeId, CancellationToken cancellationToken = default);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProvider _provider;
    private readonly HashSet<string> _processedChargeIds = [];

    public PaymentGateway(IPaymentProvider provider)
    {
        _provider = provider ?? throw new ArgumentNullException(nameof(provider));
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(cardToken))
            throw new ArgumentException("Card token is required.", nameof(cardToken));

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be greater than zero.");

        if (amount > 1_000_000m)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount exceeds maximum allowed.");

        var result = await _provider.ProcessChargeAsync(cardToken, amount, cancellationToken);

        if (result.Success)
            _processedChargeIds.Add(result.ChargeId);

        return result;
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(chargeId))
            throw new ArgumentException("Charge ID is required.", nameof(chargeId));

        if (!_processedChargeIds.Contains(chargeId))
            throw new InvalidOperationException($"Charge '{chargeId}' was not processed by this gateway.");

        var result = await _provider.ProcessRefundAsync(chargeId, cancellationToken);

        if (result.Success)
            _processedChargeIds.Remove(chargeId);

        return result;
    }

    public WebhookResult ProcessWebhook(string eventType, string payload)
    {
        if (string.IsNullOrWhiteSpace(eventType))
            throw new ArgumentException("Event type is required.", nameof(eventType));

        if (string.IsNullOrWhiteSpace(payload))
            throw new ArgumentException("Payload is required.", nameof(payload));

        return eventType switch
        {
            "charge.succeeded" => new WebhookResult(WebhookStatus.Processed, "Charge confirmed"),
            "charge.failed" => new WebhookResult(WebhookStatus.Processed, "Charge failure recorded"),
            "refund.completed" => new WebhookResult(WebhookStatus.Processed, "Refund confirmed"),
            _ => new WebhookResult(WebhookStatus.Ignored, $"Unrecognized event: {eventType}")
        };
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);
public record WebhookResult(WebhookStatus Status, string Message);

public enum WebhookStatus
{
    Processed,
    Ignored
}

