using Payments;

namespace PaymentGateway.Tests;

/// <summary>
/// Fake implementation of IPaymentProvider for testing.
/// </summary>
internal sealed class FakePaymentProvider : IPaymentProvider
{
    private int _chargeCounter;

    public bool ShouldSucceed { get; set; } = true;
    public bool ShouldThrow { get; set; }

    public Task<ChargeResult> ProcessChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();

        if (ShouldThrow)
            throw new InvalidOperationException("Provider unavailable");

        var id = $"ch_{++_chargeCounter}";
        return Task.FromResult(new ChargeResult(id, ShouldSucceed));
    }

    public Task<RefundResult> ProcessRefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();

        if (ShouldThrow)
            throw new InvalidOperationException("Provider unavailable");

        return Task.FromResult(new RefundResult($"re_{chargeId}", ShouldSucceed));
    }
}

