using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayChargeTests
{
    private readonly FakePaymentProvider _provider;
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayChargeTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new Payments.PaymentGateway(_provider);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessfulResult()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 50.00m);

        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.StartsWith("ch_", result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderFails_ReturnsUnsuccessfulResult()
    {
        _provider.ShouldSucceed = false;

        var result = await _gateway.ChargeAsync("tok_valid", 25.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    [DataRow(null)]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? cardToken)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10m));

        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRange(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));

        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaximum_ThrowsArgumentOutOfRange()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", 1_000_001m));

        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_ExactlyAtMaximum_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 1_000_000m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "Minimum valid amount")]
    [DataRow(99.99, DisplayName = "Typical amount")]
    [DataRow(1000000, DisplayName = "Maximum allowed")]
    public async Task ChargeAsync_ValidAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_PropagatesException()
    {
        _provider.ShouldThrow = true;

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task ChargeAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsAsync<OperationCanceledException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m, cts.Token));
    }

    [TestMethod]
    public async Task ChargeAsync_MultipleCharges_GeneratesUniqueIds()
    {
        var result1 = await _gateway.ChargeAsync("tok_1", 10m);
        var result2 = await _gateway.ChargeAsync("tok_2", 20m);

        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }
}

