using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayWebhookTests
{
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayWebhookTests()
    {
        _gateway = new Payments.PaymentGateway(new FakePaymentProvider());
    }

    [TestMethod]
    [DataRow("charge.succeeded", "Charge confirmed")]
    [DataRow("charge.failed", "Charge failure recorded")]
    [DataRow("refund.completed", "Refund confirmed")]
    public void ProcessWebhook_KnownEventTypes_ReturnsProcessed(string eventType, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, """{"id":"evt_1"}""");

        Assert.AreEqual(WebhookStatus.Processed, result.Status);
        Assert.AreEqual(expectedMessage, result.Message);
    }

    [TestMethod]
    [DataRow("unknown.event")]
    [DataRow("customer.created")]
    [DataRow("payout.sent")]
    public void ProcessWebhook_UnknownEventType_ReturnsIgnored(string eventType)
    {
        var result = _gateway.ProcessWebhook(eventType, """{"id":"evt_1"}""");

        Assert.AreEqual(WebhookStatus.Ignored, result.Status);
        Assert.Contains(eventType, result.Message);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    [DataRow(null)]
    public void ProcessWebhook_InvalidEventType_ThrowsArgumentException(string? eventType)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, """{"id":"evt_1"}"""));

        Assert.AreEqual("eventType", ex.ParamName);
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    [DataRow(null)]
    public void ProcessWebhook_InvalidPayload_ThrowsArgumentException(string? payload)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", payload!));

        Assert.AreEqual("payload", ex.ParamName);
    }
}

